    "m9b27807ec6b9": "Chargement des informations sur le package...",
    "m05367bca4f4f": "Forfait de renouvellement",
    "m82178d27eb16": "Instructions d'achat",
    "m83984edfeace": "Le forfait prend effet immédiatement après l'achat et les points bonus seront automatiquement rechargés sur votre compte.",
    "mf67d7542eea8": "Renouvellement du package de support",
    "m23dc677ea7fe": ": Le renouvellement du forfait actuel augmentera les points accumulés et la période de validité, et le nombre de simultanéités restera inchangé.",
    "mf8d0cda12ae7": "La limite de simultanéité détermine le nombre d'images que vous pouvez générer en même temps, améliorant ainsi l'efficacité créative",
    "m5c6d4bddf75a": "Prend en charge les mises à niveau des packages. Lors de la mise à niveau, la valeur de la durée restante sera automatiquement réduite et des limites de concurrence plus élevées seront obtenues.",
